from dsl import S, analogy, h, note, p, table, ul

SECTIONS = [
    S(
        "authentication",
        "Authentication",
        "Proving who someone is, without becoming the reason their password leaks. Store passwords safely, then make stolen and guessed passwords useless.",
        "অথেন্টিকেশন",
        "কেউ আসলে কে, তা প্রমাণ করা, এমনভাবে যাতে তার পাসওয়ার্ড ফাঁসের কারণ আপনি না হন। পাসওয়ার্ড নিরাপদে রাখুন, তারপর চুরি বা অনুমান করা পাসওয়ার্ডকে অকেজো করে দিন।",
        [
            h("Store a slow, salted hash"),
            p("A table of plain-text passwords turns any database leak into a leak of every user's password, and people reuse passwords on other sites. Store a hash instead, made with an algorithm that is deliberately slow and uses a unique random salt for each user. OWASP recommends Argon2id with at least 19 MiB of memory and 2 iterations, or bcrypt with a work factor of 10 or more on older systems [[owasp-passwords]]. A fast general-purpose hash is the wrong tool, because it lets an attacker test guesses quickly."),
            h("After login: a session"),
            p("After a successful login, the server creates a random session id and sends it in a cookie. Mark the cookie <code>Secure</code>, so it travels only over HTTPS, and <code>HttpOnly</code>, so page scripts cannot read it [[owasp-sessions]]. Issue a new session id at login, and expire idle sessions."),
            h("The forgotten-password flow"),
            p("A reset link is a key to the account, so treat it like one. Send a random token that works once and expires soon. Give the same message whether or not the email address has an account, so the form does not reveal who your users are [[owasp-forgot]]."),
            h("Credential stuffing"),
            p("Attackers take username and password pairs leaked from other sites and try them on yours, at scale. Because people reuse passwords, some pairs work [[owasp-stuffing]]. Make guessing expensive: limit failed attempts per account and per source, and add delays after repeated failures. NIST's guidelines call for rate limiting of failed attempts [[nist-63b]]."),
            h("A second factor"),
            p("Multi-factor authentication (MFA) asks for something besides the password, such as a code from an app, so a stolen password alone is not enough. OWASP calls MFA by far the best defence against most password-related attacks, credential stuffing included [[owasp-stuffing]]."),
            h("Phishing and passkeys"),
            p("A convincing fake login page can collect the password and the one-time code together and replay them at once. Passkeys resist this. They use the Web Authentication API: the device keeps a private key, the site stores only the public key, and logging in means signing a challenge, so there is no password to type or steal [[webauthn]]. A fake login site cannot use a passkey, because the signature changes with the origin of the website [[webauthn]], and FIDO describes passkeys as phishing-resistant [[fido-passkeys]]."),
            h("Or let an identity provider do it"),
            p("Sign-in is easy to get wrong, so many teams hand it to an identity provider that speaks OpenID Connect. After the user logs in, the provider returns an ID token, a signed statement of who the user is, which your app verifies [[oidc]]."),
            h("A stolen token"),
            p("Tokens can leak through logs, browser extensions or a compromised device. Keep access tokens short-lived, rotate refresh tokens on each use so that a stolen one is detected, and where possible bind tokens to the client that received them, which is called sender-constrained tokens [[rfc9700]]."),
        ],
        [
            p("A club does not keep a list of its members' secret passwords at the door. It keeps a fingerprint of each password, made by a slow machine, so even a stolen list is nearly useless. After you prove who you are, you get a wristband for the night: that is the session."),
            p("Crooks try passwords stolen from other clubs, so the door staff slow down anyone who fails several times, and ask for a second proof, such as a code on your phone. Better still is a key that only fits this club's door, so a fake door down the street cannot use it. That is a passkey."),
            analogy("<strong>A club door.</strong> The slow fingerprint is the password hash, the wristband is the session, the phone code is a second factor, and the key that only fits this door is a passkey."),
        ],
        [
            p("Plain text-এ পাসওয়ার্ড রাখলে ডেটাবেস ফাঁস মানেই সবার পাসওয়ার্ড ফাঁস, আর মানুষ একই পাসওয়ার্ড অন্য সাইটেও ব্যবহার করে। তাই রাখুন hash, এমন algorithm দিয়ে যা ইচ্ছা করে ধীর, আর প্রতিটি ব্যবহারকারীর জন্য আলাদা random salt নেয়। OWASP Argon2id সুপারিশ করে, আর পুরোনো সিস্টেমে bcrypt। লগইনের পর একটা random session id cookie-তে দিন, <code>Secure</code> আর <code>HttpOnly</code> চিহ্ন দিয়ে।"),
            p("পাসওয়ার্ড রিসেটের লিংক অ্যাকাউন্টের চাবির মতো: একবার ব্যবহারযোগ্য, দ্রুত মেয়াদ শেষ হওয়া token দিন, আর ইমেইলের অ্যাকাউন্ট থাকুক বা না থাকুক একই উত্তর দিন। আক্রমণকারী অন্য সাইট থেকে ফাঁস হওয়া পাসওয়ার্ড আপনার সাইটে চেষ্টা করে, একে credential stuffing বলে। তাই ব্যর্থ চেষ্টার সংখ্যা সীমিত করুন, আর দ্বিতীয় প্রমাণ (MFA) চান।"),
            p("নকল লগইন পেজ পাসওয়ার্ড আর OTP দুটোই হাতিয়ে নিতে পারে। Passkey এটা ঠেকায়: ডিভাইসে থাকে private key, সাইটে শুধু public key, আর লগইন হয় সই করা challenge দিয়ে। টাইপ বা চুরি করার মতো কোনো পাসওয়ার্ড নেই, আর passkey শুধু নিজের সাইটেই কাজ করে। চাইলে OpenID Connect দিয়ে একটা identity provider-কে লগইনের দায়িত্ব দিন। আর token চুরির ক্ষতি কমাতে access token-এর মেয়াদ ছোট রাখুন, refresh token প্রতিবার ব্যবহারে বদলান।"),
            analogy("<strong>ক্লাবের দরজা:</strong> ধীর মেশিনে বানানো আঙুলের ছাপ হলো পাসওয়ার্ড hash, রাতের রিস্টব্যান্ড হলো session, ফোনের কোড হলো দ্বিতীয় প্রমাণ, আর শুধু এই দরজায় লাগা চাবি হলো passkey।"),
        ],
    ),
    S(
        "authorization",
        "Authorization",
        "Knowing who someone is does not tell you what they may see or do. Check permission on every request, for every object.",
        "অথরাইজেশন",
        "কেউ কে, তা জানলেই জানা যায় না সে কী দেখতে বা করতে পারবে। প্রতিটি রিকোয়েস্টে, প্রতিটি জিনিসের জন্য অনুমতি যাচাই করুন।",
        [
            h("Change the URL"),
            p("Alice is logged in and opens <code>/orders/1001</code>. She changes it to <code>/orders/1002</code> and sees a stranger's order. The server checked who she was, but not whether order 1002 is hers. This is broken object level authorization, the first risk on the OWASP API Security Top 10 [[owasp-bola]]."),
            h("Check ownership on every request"),
            p("Every endpoint that takes an object id must check that the current user may access that object, for example by querying <code>WHERE id = ? AND owner_id = ?</code> instead of by id alone. A check in the user interface is not enough, because anyone can call the API directly."),
            h("Mass assignment"),
            p("A profile update accepts JSON and copies every field into the user record. An attacker adds <code>\"role\": \"admin\"</code> and is promoted. Copy only an explicit allow-list of the fields a client may change [[owasp-bopla]]."),
            h("Let the database enforce tenants too"),
            p("In a multi-tenant app, one forgotten <code>WHERE tenant_id = ?</code> leaks data between customers. PostgreSQL's row security policies make the database filter rows by policy on every query, a second line of defence [[pg-rls]]."),
            h("Roles, relationships and policy"),
            ul(
                "<strong>Roles.</strong> Role-based access control (RBAC) grants permissions to roles such as viewer, editor and admin, and gives roles to users [[nist-rbac]].",
                "<strong>Relationships.</strong> Sharing a document with a person or a team needs permissions that follow relationships. Google's Zanzibar stores such relationships and answers access checks for many Google services [[zanzibar]].",
                "<strong>Central policy.</strong> When rules are scattered through the code, nobody can review them. A policy engine such as Open Policy Agent decouples the decision from the code that enforces it [[opa]].",
            ),
            h("Least privilege"),
            p("A service with database admin rights and keys to every bucket turns any bug in it into a full breach. Grant each service and each person only the permissions they need [[aws-least-priv]]."),
            h("The confused deputy"),
            p("A service with broad rights can be tricked into using them for a caller who lacks them, for example by fetching a file that the caller names. This is the confused deputy problem [[aws-confused-deputy]]. Act on behalf of the user, with the user's rights: pass their identity downstream, or exchange their token for a narrower one, as OAuth 2.0 Token Exchange defines [[rfc8693]]."),
            h("Audit logs"),
            p("Record who did what to which object, and when, especially for reads of sensitive data and for changes to permissions. Protect these logs from tampering, including by the people whose actions they record [[owasp-logging]]."),
        ],
        [
            p("A hotel key card proves you are a guest, but it should only open your own room. If each lock just checked \"is this a guest card?\", any guest could open any room by trying door numbers."),
            p("Good hotels check the room at every door, give cleaners cards that open only their floor, keep the master key locked away, and log which card opened which door and when. If a guest asks the front desk to fetch something from \"my room\", the desk first checks that it really is their room."),
            analogy("<strong>Hotel key cards.</strong> The guest card is authentication, opening only your room is the ownership check, the cleaner's floor card is a role, and the door log is the audit log."),
        ],
        [
            p("Alice লগইন করে <code>/orders/1001</code> খুলল, তারপর URL বদলে <code>/orders/1002</code> করে একজন অপরিচিতের অর্ডার দেখে ফেলল। সার্ভার যাচাই করেছে সে কে, কিন্তু অর্ডারটা তার কি না তা দেখেনি। একে broken object level authorization বলে, OWASP API Security Top 10-এর প্রথম ঝুঁকি। তাই প্রতিটি endpoint-এ যাচাই করুন বর্তমান ব্যবহারকারী ওই জিনিসটা দেখতে পারে কি না, যেমন <code>WHERE id = ? AND owner_id = ?</code>।"),
            p("Profile আপডেটে client যেকোনো ফিল্ড পাঠাতে পারলে কেউ <code>role</code> ফিল্ডে admin লিখে দিতে পারে; তাই শুধু অনুমোদিত ফিল্ডের তালিকা থেকে কপি করুন। Multi-tenant অ্যাপে ডেটাবেসের row-level security দ্বিতীয় স্তরের সুরক্ষা দেয়। RBAC-এ viewer, editor, admin-এর মতো role-কে অনুমতি দিন, আর ব্যবহারকারীকে role দিন। শেয়ার করার মতো সম্পর্কভিত্তিক অনুমতির জন্য Google-এর Zanzibar-এর মতো সিস্টেম আছে, আর নিয়মগুলো এক জায়গায় রাখতে Open Policy Agent-এর মতো policy engine ব্যবহার করা যায়।"),
            p("প্রতিটি সার্ভিস আর মানুষকে শুধু দরকারি অনুমতি দিন (least privilege)। বেশি ক্ষমতার সার্ভিসকে ধোঁকা দিয়ে অন্যের হয়ে কাজ করানো যায়; একে confused deputy বলে। তাই ব্যবহারকারীর নিজের অনুমতি নিয়ে কাজ করুন, তার পরিচয় নিচের সার্ভিসে পাঠিয়ে। আর audit log রাখুন: কে, কখন, কোন জিনিসে কী করেছে।"),
            analogy("<strong>হোটেলের কী কার্ড:</strong> অতিথির কার্ড হলো authentication, শুধু নিজের রুম খোলা হলো ownership check, ক্লিনারের ফ্লোর কার্ড হলো role, আর দরজার লগ হলো audit log।"),
        ],
    ),
    S(
        "encryption",
        "Encryption & Secrets",
        "Protect data on the wire and on disk, and protect the keys and passwords your services use. Many leaks start with a secret in the wrong place.",
        "এনক্রিপশন আর সিক্রেট",
        "নেটওয়ার্কে চলার সময় আর ডিস্কে থাকার সময় ডেটা সুরক্ষিত রাখুন, সাথে সার্ভিসগুলোর key আর পাসওয়ার্ডও। অনেক ফাঁস শুরু হয় ভুল জায়গায় রাখা একটা সিক্রেট থেকে।",
        [
            h("Encrypt the wire: TLS"),
            p("On a café's Wi-Fi, plain HTTP can be read and changed by anyone on the network. TLS encrypts the connection and authenticates the server with a certificate, so the client knows it is talking to the real site [[rfc8446]]. Serve everything over HTTPS."),
            h("Certificates expire"),
            p("A certificate that expires at 3 a.m. takes the site down as surely as a crash. Automate renewal. Let's Encrypt issues certificates that last ninety days today (shortening to 64 days in February 2027 and 45 days by 2028), partly to push everyone towards automation [[le-90-days]]. Alert well before any certificate expires."),
            h("Encrypt inside the data center too"),
            p("A network perimeter is not a guarantee. An attacker who gets inside should not be able to read the traffic between services. Zero trust architecture drops the assumption that anything inside the network can be trusted [[nist-zero-trust]]. In practice, services authenticate each other and encrypt their traffic with mutual TLS, often through a service mesh (section 29)."),
            h("Encrypt at rest, keep the keys elsewhere"),
            p("A stolen disk or backup should be unreadable. Encrypt data at rest, and keep the keys in a separate key management service (KMS). With envelope encryption, a data encryption key (DEK) encrypts the data, and a key encryption key (KEK) in the KMS encrypts the DEK [[gcp-envelope]]. The backup then holds only encrypted data and encrypted keys."),
            h("Rotate keys"),
            p("Keys should change regularly, and at once after a suspected leak. A KMS can rotate a key's material on a schedule while it keeps the older versions, so data encrypted earlier still decrypts [[aws-kms-rotate]]."),
            h("Secrets out of the code"),
            p("A database password committed to Git stays in the history even after it is deleted from the latest version. Secret scanning tools search repositories, including their history, for known kinds of secrets [[gh-secret-scanning]]. If a secret leaks, rotate it first and clean up afterwards."),
            p("Keep secrets in a secrets manager and inject them at runtime, with access control and an audit trail [[owasp-secrets]]. Better still, issue short-lived credentials. Vault's database secrets engine creates database credentials dynamically, each with a lease after which it is revoked [[vault-dynamic]]."),
            h("Tokenize card numbers"),
            p("If you store card numbers, every system that touches them falls under the card industry's security rules. Tokenization replaces each card number (the PAN) with a token that is useless on its own, while a separate, hardened vault keeps the mapping. Systems that see only tokens can then fall outside much of that scope [[pci-token]]."),
            h("End-to-end encryption"),
            p("With end-to-end encryption only the users' devices hold the keys, so even the server cannot read the messages. The Signal Protocol uses a key agreement (X3DH, now extended to the post-quantum PQXDH) and the Double Ratchet algorithm for this [[signal-docs]]. The trade-off is that the server cannot search, scan or recover message content for the user."),
        ],
        [
            p("Sending a postcard lets every postman read it. Sending a sealed, tamper-proof envelope is TLS. Keeping envelopes sealed even inside your own office building is encryption inside the data center."),
            p("A locked safe is no use if the key is taped to its door, so keys live somewhere else and are changed now and then. Nobody leaves a spare key under the doormat, which is what a password in your code is. And a cloakroom ticket that stands in for your coat is a token: worthless to a thief without the cloakroom."),
            analogy("<strong>Envelopes and safes.</strong> The sealed envelope is TLS, the safe is encryption at rest, the key kept elsewhere is the KMS, and the cloakroom ticket is tokenization."),
        ],
        [
            p("ক্যাফের Wi-Fi-তে সাধারণ HTTP নেটওয়ার্কের যে কেউ পড়তে আর বদলাতে পারে। TLS connection এনক্রিপ্ট করে, আর certificate দিয়ে প্রমাণ করে আপনি আসল সাইটের সাথেই কথা বলছেন। Certificate-এর মেয়াদ শেষ হলে সাইট বন্ধ হয়ে যায়, তাই নবায়ন স্বয়ংক্রিয় করুন; Let's Encrypt এখন ৯০ দিনের certificate দেয় (২০২৭-এর ফেব্রুয়ারিতে ৬৪ দিন, ২০২৮-এর মধ্যে ৪৫ দিন হবে), অংশত এই কারণেই। ভেতরের নেটওয়ার্ককেও অন্ধভাবে বিশ্বাস করবেন না (zero trust): সার্ভিসগুলোর মধ্যেও mutual TLS ব্যবহার করুন।"),
            p("চুরি হওয়া ডিস্ক বা backup যেন পড়া না যায়, সেজন্য ডেটা এনক্রিপ্ট করে রাখুন, আর key রাখুন আলাদা key management service (KMS)-এ। Envelope encryption-এ একটা data key ডেটা এনক্রিপ্ট করে, আর KMS-এর key সেই data key-কে এনক্রিপ্ট করে। Key নিয়মিত বদলান (rotation); পুরোনো ভার্সন রাখা হয়, যাতে আগের ডেটা খোলা যায়।"),
            p("Git-এ commit করা পাসওয়ার্ড পরের ভার্সনে মুছলেও ইতিহাসে থেকে যায়; ফাঁস হলে আগে সেটা বদলান। সিক্রেট রাখুন secrets manager-এ, চালুর সময় ঢোকান, আর সম্ভব হলে Vault-এর মতো টুল দিয়ে স্বল্পমেয়াদি credential দিন। কার্ড নম্বর নিজে না রেখে token রাখুন (tokenization)। আর end-to-end encryption-এ শুধু ব্যবহারকারীদের ডিভাইসে key থাকে, তাই সার্ভারও message পড়তে পারে না; Signal Protocol এভাবে কাজ করে।"),
            analogy("<strong>খাম আর সিন্দুক:</strong> সিল করা খাম হলো TLS, সিন্দুক হলো encryption at rest, অন্য জায়গায় রাখা চাবি হলো KMS, আর ক্লোকরুমের টোকেন হলো tokenization।"),
        ],
    ),
]
